def calculate_reciprocal(x):
    # الدالة دي بتمثل f(x) = 1/x
    # الـ Domain هنا هو كل الأرقام ما عدا الصفر
    if x == 0:
        return "Error: Division by zero is not allowed!"
    else:
        return 1 / x

# تجربة المدخلات (Dry Run)
print(calculate_reciprocal(5))   # المخرج: 0.2 (قيمة داخل الـ Range)
print(calculate_reciprocal(0))   # المخرج: رسالة خطأ (خارج الـ Domain)

